```tsx
import "./StreakBadge.css";

export interface StreakBadgeProps {
  /** Current day of the streak, counted from 1. */
  day: number;
  /** Total number of days in the streak challenge. */
  total: number;
}

export function StreakBadge({ day, total }: StreakBadgeProps) {
  const safeTotal = Number.isFinite(total) && total > 0 ? Math.floor(total) : 1;
  const rawDay = Number.isFinite(day) ? Math.floor(day) : 0;
  const safeDay = Math.min(Math.max(rawDay, 0), safeTotal);
  const ratio = safeDay / safeTotal;
  const label = `Day ${safeDay} of ${safeTotal}`;

  return (
    <div
      className="streak-badge"
      role="group"
      aria-label={`Streak progress: ${label}`}
      tabIndex={0}
    >
      <span className="streak-badge__label">{label}</span>
      <div
        className="streak-badge__track"
        role="progressbar"
        aria-label="Streak progress"
        aria-valuemin={0}
        aria-valuemax={safeTotal}
        aria-valuenow={safeDay}
        aria-valuetext={label}
      >
        <span
          className="streak-badge__fill"
          style={{ transform: `scaleX(${ratio})` }}
        />
      </div>
    </div>
  );
}
```

