/* Day theme tokens (default). */
.streak-badge {
  --streak-badge-bg: #f4f1ea;
  --streak-badge-text: #2a2722;
  --streak-badge-track: #ddd6c8;
  --streak-badge-fill: #3f6b5a;
  --streak-badge-focus: #1d4a3b;
  --streak-badge-border: #cfc6b4;

  display: inline-flex;
  flex-direction: column;
  gap: 0.4rem;
  min-width: 9rem;
  padding: 0.6rem 0.9rem;
  border: 1px solid var(--streak-badge-border);
  border-radius: 0.6rem;
  background: var(--streak-badge-bg);
  color: var(--streak-badge-text);
  font: 500 0.875rem/1.2 system-ui, -apple-system, "Segoe UI", sans-serif;
  letter-spacing: 0.01em;
  box-sizing: border-box;
  user-select: none;
  transition: border-color 160ms ease, background-color 160ms ease;
}

/* Night theme tokens. */
[data-theme="night"] .streak-badge {
  --streak-badge-bg: #1b1f24;
  --streak-badge-text: #e6e9ee;
  --streak-badge-track: #2e353d;
  --streak-badge-fill: #7fb8a0;
  --streak-badge-focus: #a8d8c2;
  --streak-badge-border: #323a44;
}

.streak-badge:hover {
  border-color: var(--streak-badge-fill);
}

.streak-badge:focus {
  outline: none;
}

.streak-badge:focus-visible {
  outline: 2px solid var(--streak-badge-focus);
  outline-offset: 2px;
}

.streak-badge__label {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.streak-badge__track {
  position: relative;
  width: 100%;
  height: 0.3rem;
  border-radius: 999px;
  background: var(--streak-badge-track);
  overflow: hidden;
}

.streak-badge__fill {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: var(--streak-badge-fill);
  transform-origin: left center;
  transition: transform 300ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .streak-badge,
  .streak-badge__fill {
    transition: none;
  }
}
